import heapq, time
from collections import defaultdict, deque
from urllib.parse import urlsplit

class Frontier:
    def __init__(self, default_delay_s: float = 1.0):
        self.delay = default_delay_s
        self.queues = defaultdict(deque)   # host -> URLs: one back queue per host
        self.heap = []                     # (earliest next fetch, host)
        self.active = set()                # hosts in the heap or being fetched

    def add(self, url: str) -> None:
        host = urlsplit(url).hostname
        self.queues[host].append(url)
        if host not in self.active:        # idle host: eligible right away
            self.active.add(host)
            heapq.heappush(self.heap, (time.monotonic(), host))

    def next(self) -> tuple[str, str] | None:
        if not self.heap or self.heap[0][0] > time.monotonic():
            return None                    # no host is due yet
        _, host = heapq.heappop(self.heap)
        return host, self.queues[host].popleft()

    def done(self, host: str, crawl_delay_s: float | None = None) -> None:
        # Reschedule only after the fetch ends: one request in flight per host
        if self.queues[host]:
            due = time.monotonic() + (crawl_delay_s or self.delay)
            heapq.heappush(self.heap, (due, host))
        else:
            self.active.discard(host)
            del self.queues[host]
